bility-esg-report-ada.pdf","deal_value":null,"deal_currency":null,"deal_value_basis":null,"stake_pct":null,"co_investors":[],"deal_source_url":null},{"name":"Tullahennel","slug":"tullahennel","domain":null,"description":"Wind power asset in Ireland acquired by Apollo-managed funds.","sector":"Renewable energy","hq":"Ireland","status":null,"invested_year":null,"exit_year":null,"fund_name":null,"source_url":"https://www.apollo.com/content/dam/apolloaem/documents/insights/apollo-driving-sustainability-esg-report-ada.pdf","deal_value":null,"deal_currency":null,"deal_value_basis":null,"stake_pct":null,"co_investors":[],"deal_source_url":null},{"name":"Arthur Kill Terminal","slug":"arthur-kill-terminal","domain":null,"description":"Offshore wind staging and assembly port under development on Staten Island, New York, in which Apollo funds are investing.","sector":"Infrastructure","hq":"Staten Island, New York","status":null,"invested_year":2021,"exit_year":null,"fund_name":null,"source_url":"https://www.apollo.com/content/dam/apolloaem/documents/insights/apollo-2023-sustainability-report-june-2024.pdf","deal_value":null,"deal_currency":null,"deal_value_basis":null,"stake_pct":null,"co_investors":[],"deal_source_url":null},{"name":"Sparrow's Point Steel","slug":"sparrow-s-point-steel","domain":null,"description":"Offshore wind supply-chain manufacturing project to which Apollo funds have early-stage exposure.","sector":"Infrastructure","hq":null,"status":null,"invested_year":null,"exit_year":null,"fund_name":null,"source_url":"https://www.apollo.com/content/dam/apolloaem/documents/insights/apollo-2023-sustainability-report-june-2024.pdf","deal_value":null,"deal_currency":null,"deal_value_basis":null,"stake_pct":null,"co_investors":[],"deal_source_url":null},{"name":"Motor Fuel Group (MFG)","slug":"motor-fuel-group-mfg","domain":null,"description":"UK forecourt convenience operator; investors led by Apollo Hybrid Value bought a minority structured equity stake from CD&R funds.","sector":"Retail","hq":"UK","status":null,"invested_year":2025,"exit_year":null,"fund_name":null,"source_url":"https://www.cdr.com/news/cd-and-r-announces-the-sale-of-a-minority-stake-in-mfg-to-a-group-of-leading-institutional-investors-led-by-apollo-hybrid-value","deal_value":null,"deal_currency":null,"deal_value_basis":null,"stake_pct":null,"co_investors":[],"deal_source_url":null},{"name":"Syntegon","slug":"syntegon","domain":null,"description":"Processing and packaging technology supplier to pharma, biotech and food; an Apollo-led investor group acquired about a 37% stake from CVC.","sector":"Industrials","hq":null,"status":null,"invested_year":2026,"exit_year":null,"fund_name":null,"source_url":"https://www.cvc.com/media/news/2026/cvc-welcomes-apollo-as-minority-investor-in-syntegon-partnership-to-accelerate-next-growth-phase/","deal_value":null,"deal_currency":null,"deal_value_basis":null,"stake_pct":null,"co_investors":[],"deal_source_url":null},{"name":"Aleris","slug":"aleris","domain":null,"description":"US aluminum company; Apollo, Oaktree and Sankaty became owners in 2010 after its Chapter 11 filing.","sector":"Materials","hq":null,"status":null,"invested_year":2010,"exit_year":null,"fund_name":null,"source_url":"https://en.wikipedia.org/wiki/Aleris","deal_value":null,"deal_currency":null,"deal_value_basis":null,"stake_pct":null,"co_investors":[],"deal_source_url":null},{"name":"Bradco Supply","slug":"bradco-supply","domain":null,"description":"US building materials distributor in which Apollo Management acquired a minority interest in 2007.","sector":"Building products distribution","hq":null,"status":null,"invested_year":2007,"exit_year":null,"fund_name":null,"source_url":"https://en.wikipedia.org/wiki/Bradco_Supply","deal_value":null,"deal_currency":null,"deal_value_basis":null,"stake_pct":null,"co_investors":[],"deal_source_url":null},{"name":"CEVA Logistics","slug":"ceva-logistics","domain":null,"description":"Logistics and supply chain company listed among Apollo Global Management companies on Wikipedia.","sector":"Logistics","hq":"Marseille","status":null,"invested_year":null,"exit_year":null,"fund_name":null,"source_url":"https://en.wikipedia.org/wiki/Category:Apollo_Global_Management_companies","deal_value":null,"deal_currency":null,"deal_value_basis":null,"stake_pct":null,"co_investors":[],"deal_source_url":null}],"deals":[]}$pf$::jsonb;
  n_companies int;
  n_deals int;
begin
  select id into gp from public.companies
   where category = 'GP' and name = 'Apollo Global Management'
   order by (source = 'master_directory') desc nulls last, created_at
   limit 1;
  if gp is null then raise exception 'sponsor % is not in the directory', 'Apollo Global Management'; end if;

  insert into public.portfolio_companies as pc (external_key, gp_company_id, name, domain, description, sector, hq, status, invested_year, exit_year, fund_name,
      source, source_url, deal_value, deal_currency, deal_value_basis, stake_pct, co_investors, deal_source_url, researched_at)
  select gp::text || ':' || (c->>'slug'), gp, c->>'name', c->>'domain', c->>'description', c->>'sector', c->>'hq', c->>'status',
         (c->>'invested_year')::int, (c->>'exit_year')::int, c->>'fund_name', 'web_research', c->>'source_url',
         (c->>'deal_value')::numeric, c->>'deal_currency', c->>'deal_value_basis', (c->>'stake_pct')::numeric,
         coalesce(array(select jsonb_array_elements_text(c->'co_investors')), '{}'), c->>'deal_source_url', now()
    from jsonb_array_elements(doc->'companies') c
  on conflict (external_key) do update set
    name = case when pc.source = 'manual' then pc.name else excluded.name end,
    domain = coalesce(pc.domain, excluded.domain),
    description = case when pc.source = 'manual' then coalesce(pc.description, excluded.description) else coalesce(excluded.description, pc.description) end,
    sector = case when pc.source = 'manual' then coalesce(pc.sector, excluded.sector) else coalesce(excluded.sector, pc.sector) end,
    hq = case when pc.source = 'manual' then coalesce(pc.hq, excluded.hq) else coalesce(excluded.hq, pc.hq) end,
    status = coalesce(excluded.status, pc.status),
    invested_year = coalesce(excluded.invested_year, pc.invested_year),
    exit_year = coalesce(excluded.exit_year, pc.exit_year),
    fund_name = coalesce(excluded.fund_name, pc.fund_name),
    source_url = case when pc.source = 'manual' then coalesce(pc.source_url, excluded.source_url) else excluded.source_url end,
    deal_value = coalesce(excluded.deal_value, pc.deal_value),
    deal_currency = case when excluded.deal_value is not null then excluded.deal_currency else pc.deal_currency end,
    deal_value_basis = case when excluded.deal_value is not null then excluded.deal_value_basis else pc.deal_value_basis end,
    stake_pct = coalesce(excluded.stake_pct, pc.stake_pct),
    co_investors = case when cardinality(excluded.co_investors) > 0 then excluded.co_investors else pc.co_investors end,
    deal_source_url = coalesce(excluded.deal_source_url, pc.deal_source_url),
    researched_at = now();
  get diagnostics n_companies = row_count;

  insert into public.deals as d (external_key, date, date_text, kind, asset_class, target, target_kind, target_key, target_website, investor, investor_company_id,
      co_investors, seller, round, stake_pct, amount, currency, amount_basis, valuation, valuation_currency, headline, summary, source_name, source_url,
      evidence, verified, source)
  select x->>'key', (x->>'date')::date, x->>'date_text', x->>'kind', x->>'asset_class', x->>'target', 'company',
         public.borrower_key(coalesce(x->>'portco_name', x->>'target')), x->>'target_website', x->>'investor',
         case when (x->>'sponsor_is_investor')::boolean then gp else (select m.company_id from ingest.match_firm(x->>'investor', array['GP']) m) end,
         coalesce(array(select jsonb_array_elements_text(x->'co_investors')), '{}'), x->>'seller', x->>'round', (x->>'stake_pct')::numeric,
         (x->>'amount')::numeric, x->>'currency', x->>'amount_basis', (x->>'valuation')::numeric, x->>'valuation_currency',
         x->>'headline', x->>'summary', x->>'source_name', x->>'source_url', x->>'evidence', (x->>'verified')::boolean, 'web_research'
    from jsonb_array_elements(doc->'deals') x
  on conflict (external_key) do update set
    date = excluded.date, date_text = excluded.date_text, kind = excluded.kind, target = excluded.target, target_key = excluded.target_key,
    target_website = coalesce(excluded.target_website, d.target_website), investor = excluded.investor,
    investor_company_id = coalesce(excluded.investor_company_id, d.investor_company_id),
    co_investors = (select coalesce(array_agg(distinct v), '{}') from unnest(d.co_investors || excluded.co_investors) v),
    seller = coalesce(excluded.seller, d.seller), round = coalesce(excluded.round, d.round), stake_pct = coalesce(excluded.stake_pct, d.stake_pct),
    amount = excluded.amount, currency = excluded.currency, amount_basis = excluded.amount_basis,
    valuation = excluded.valuation, valuation_currency = excluded.valuation_currency, headline = excluded.headline,
    summary = coalesce(excluded.summary, d.summary), source_name = excluded.source_name, source_url = excluded.source_url,
    evidence = excluded.evidence, verified = coalesce(excluded.verified, d.verified);
  get diagnostics n_deals = row_count;

  update public.companies set portfolio_note = 'Apollo''s site has no portfolio list; built from Apollo''s own disclosures: every ir.apollo.com press release 2011-2026 (sitemap, 649 releases) and apollo.com/insights-news press releases, the Appendix A ''Reporting Companies'' listings in Apollo''s Responsible & Sustainable Portfolio Supplements 2022-2025 and ESG reports 2019-2021 (2025 listing = status current), Apollo''s origination/financial-service', portfolio_researched_at = now() where id = gp;
  insert into ingest.log (what, detail) values ('load_portfolio', jsonb_build_object('sponsor', 'Apollo Global Management', 'companies', n_companies, 'deals', n_deals));
end $pfdo$;
